const SB_URL = $env.SUPABASE_URL;
const SB_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const http = this.helpers.httpRequest;
if (!SB_URL || !SB_KEY) return [{ json: { skipped: true, reason: 'SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY not set' } }];

function rest(path, opts) {
  opts = opts || {};
  return http(Object.assign({ url: SB_URL + '/rest/v1/' + path, json: true }, opts, {
    headers: Object.assign({ apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' }, opts.headers || {}),
  }));
}
function normDomain(d) {
  if (!d) return '';
  return String(d).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').trim();
}
function hostOf(u) { try { return normDomain(new URL(u).host); } catch { return normDomain(u); } }

// Curated, REAL venues. Broadly applicable to B2B software/products; a human
// prunes what does not fit each product. Community/wiki entries are suggestions
// for MANUAL participation — the system never posts to them.
const CATALOG = [
  { type: 'directory',   name: 'Clutch',          url: 'https://clutch.co',          note: 'B2B services/software directory; submit a verified company profile.' },
  { type: 'directory',   name: 'GoodFirms',       url: 'https://www.goodfirms.co',   note: 'B2B software & services directory; claim/submit a profile.' },
  { type: 'directory',   name: 'DesignRush',      url: 'https://www.designrush.com', note: 'Agency/vendor directory; submit a listing.' },
  { type: 'directory',   name: 'Sulekha',         url: 'https://www.sulekha.com',    note: 'India local business directory.' },
  { type: 'directory',   name: 'Justdial',        url: 'https://www.justdial.com',   note: 'India local business directory.' },
  { type: 'review_site', name: 'G2',              url: 'https://www.g2.com',         note: 'Software review platform; create a product profile, earn genuine reviews (never fake).' },
  { type: 'review_site', name: 'Capterra',        url: 'https://www.capterra.com',   note: 'Software review platform; create a listing, earn genuine reviews (never fake).' },
  { type: 'review_site', name: 'SoftwareSuggest', url: 'https://www.softwaresuggest.com', note: 'India software review/listing platform.' },
  { type: 'press',       name: 'YourStory',       url: 'https://yourstory.com',      note: 'Indian startup/tech press; pitch a genuine story.' },
  { type: 'press',       name: 'Inc42',           url: 'https://inc42.com',          note: 'Indian startup/tech press; pitch a genuine story.' },
  { type: 'community',   name: 'Product Hunt',    url: 'https://www.producthunt.com', note: 'Launch venue; MANUAL participation only, respect platform rules — system does not post.' },
  { type: 'community',   name: 'Indie Hackers',   url: 'https://www.indiehackers.com', note: 'Community; MANUAL participation only, respect self-promo rules — system does not post.' },
  { type: 'wiki_source', name: 'Independent coverage (Wikipedia-eligible)', url: 'https://en.wikipedia.org/wiki/Wikipedia:Reliable_sources', note: 'Earn coverage in independent reliable sources so the entity becomes citable; NEVER self-edit Wikipedia.' },
];

// Load entities (self), their queries, gaps, competitors, and probe source_urls.
const entities = await rest('tracked_entities?select=id,name,domain,type&type=eq.self');
const queries = await rest('target_queries?select=id,entity_id');
const gaps = await rest('visibility_gaps?select=query_id');
const competitors = await rest('competitors?select=entity_id,domain');
const checks = await rest('visibility_checks?select=query_id,source_urls');

const entityByQuery = {};
for (const q of queries) entityByQuery[q.id] = q.entity_id;
const gapCountByEntity = {};
for (const g of gaps) { const e = entityByQuery[g.query_id]; if (e) gapCountByEntity[e] = (gapCountByEntity[e] || 0) + 1; }
const ourDomains = {}; for (const e of entities) if (e.domain) ourDomains[normDomain(e.domain)] = true;
const competitorDomains = {}; for (const c of competitors) competitorDomains[normDomain(c.domain)] = true;

// third-party source domains per entity, from probe source_urls
const sourcesByEntity = {};
for (const ch of checks) {
  const e = entityByQuery[ch.query_id]; if (!e) continue;
  const urls = Array.isArray(ch.source_urls) ? ch.source_urls : [];
  for (const u of urls) {
    const d = hostOf(u);
    if (!d || ourDomains[d]) continue; // skip our own
    (sourcesByEntity[e] = sourcesByEntity[e] || {})[d] = true;
  }
}

// process entities most-gaps-first (prioritisation)
const ordered = entities.slice().sort((a, b) => (gapCountByEntity[b.id] || 0) - (gapCountByEntity[a.id] || 0));

const rows = [];
for (const ent of ordered) {
  const gapN = gapCountByEntity[ent.id] || 0;
  // (a) curated catalog
  for (const c of CATALOG) {
    rows.push({ entity_id: ent.id, type: c.type, name: c.name, url: c.url, relevance_note: c.note + ' · ' + ent.name + ' has ' + gapN + ' visibility gap(s).', status: 'identified' });
  }
  // (b) third-party sources already surfacing for this entity's queries
  const srcs = Object.keys(sourcesByEntity[ent.id] || {});
  for (const d of srcs) {
    const competitorCited = competitorDomains[d] ? false : true; // competitor root domains are not "sources"
    if (!competitorCited) continue;
    rows.push({
      entity_id: ent.id,
      type: 'press',
      name: d,
      url: 'https://' + d,
      relevance_note: 'Third-party source already surfacing in AI/search results for this entity’s queries (from probe source_urls) — a place competitors get cited, so pitch genuine coverage here.',
      status: 'identified',
    });
  }
}

// idempotent upsert: ignore duplicates so human-progressed status is preserved
let inserted = 0;
if (rows.length) {
  // chunk to keep requests small
  for (let i = 0; i < rows.length; i += 100) {
    const chunk = rows.slice(i, i + 100);
    await rest('citation_targets?on_conflict=entity_id,url', {
      method: 'POST',
      headers: { Prefer: 'resolution=ignore-duplicates,return=minimal' },
      body: chunk,
    });
    inserted += chunk.length;
  }
}
return [{ json: { entities: ordered.length, candidates_upserted: inserted, note: 'duplicates ignored; existing statuses preserved' } }];
